changeSet.sql:
CREATE INDEX idx_locations_geom       ON locations USING GIST(geom);
CREATE INDEX idx_locations_category   ON locations(category);
CREATE INDEX idx_locations_is_default ON locations(is_default);

changeSet.createProcedure:
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

changeSet.sql:
CREATE TRIGGER locations_updated_at
BEFORE UPDATE ON locations
FOR EACH ROW EXECUTE FUNCTION update_updated_at();

INSERT INTO locations (name, category, latitude, longitude, geom, is_default) SELECT src.name, src.category, src.latitude, src.longitude, ST_SetSRID(ST_MakePoint(src.longitude, src.latitude), 4326) AS geom, true FROM ( SELECT p.name, COALESCE( p.amenity, p.shop, p.tourism, p.leisure, p.sport, p.office, p.historic, p.man_made, p.landuse ) AS category, ST_Y(ST_Transform(p.way, 4326)) AS latitude, ST_X(ST_Transform(p.way, 4326)) AS longitude FROM planet_osm_point p WHERE p.name IS NOT NULL AND TRIM(p.name) <> ''
UNION ALL
SELECT poly.name, COALESCE( poly.amenity, poly.shop, poly.tourism, poly.leisure, poly.sport, poly.office, poly.historic, poly.man_made, poly.landuse ) AS category, ST_Y(ST_PointOnSurface(ST_Transform(poly.way, 4326))) AS latitude, ST_X(ST_PointOnSurface(ST_Transform(poly.way, 4326))) AS longitude FROM planet_osm_polygon poly WHERE poly.name IS NOT NULL AND TRIM(poly.name) <> '' AND poly.way IS NOT NULL ) src WHERE src.category IN ( 'school', 'pub', 'place_of_worship', 'restaurant', 'fast_food', 'cafe', 'convenience', 'hairdresser', 'parking', 'sports_centre', 'fuel', 'community_centre', 'supermarket', 'fitness_centre', 'pharmacy', 'hotel', 'pitch', 'post_office', 'park', 'memorial', 'charging_station', 'bank', 'social_facility', 'retail', 'attraction', 'bar', 'forest', 'farmyard', 'meadow', 'lawyer' );
